(5,'gouvernance_organisation','Gouvernance et organisation','Gouvernance','SMSI, organisation de la sécurité, comités, plan d\'action, amélioration continue, chartes d\'entreprise, processus.',1,'2026-09-08 15:06:59','2026-09-08 23:32:45','biennal'),
(6,'securite_reseau','Sécurité du réseau','Technique','Architecture réseau, filtrage, cloisonnement, flux, DMZ, passerelles, proxy, DNS, Wi-Fi, interconnexions, protocoles réseau.',1,'2026-09-08 15:06:59','2026-09-08 23:32:45','biennal'),
